import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Container, Row, Col, Card, Table, Button, Badge, 
  Form, Modal, Alert, InputGroup 
} from 'react-bootstrap';
import { apiService, PurchaseOrder, PurchaseRequest } from '../services/api';
import { useAuth } from '../contexts/AuthContext';
import LoadingSpinner from '../components/LoadingSpinner';
import Toast from '../components/Toast';

const Inspection: React.FC = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [orders, setOrders] = useState<PurchaseOrder[]>([]);
  const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<PurchaseOrder | null>(null);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info'>('info');
  const [searchTerm, setSearchTerm] = useState('');

  // Inspection form state
  const [inspectionData, setInspectionData] = useState({
    inspection_date: new Date().toISOString().split('T')[0],
    inspected_by: user?.full_name || user?.username || '',
    items: [] as Array<{
      item_description: string;
      quantity_received: number;
      quantity_ordered: number;
      condition: 'Good' | 'Defective' | 'Damaged';
      remarks: string;
    }>,
    overall_remarks: '',
    status: 'Pending' as 'Pending' | 'Accepted' | 'Rejected' | 'Partial'
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      
      // Fetch purchase orders that are approved and ready for inspection
      try {
        // For inspector, we need to get approved purchase orders or purchase requests with approved status
        const purchaseRequests = await apiService.getPurchaseRequests(false);
        const approvedRequests = purchaseRequests.filter(pr => 
          pr.status === 'Approved' || pr.status === 'Completed'
        );
        
        // Convert purchase requests to purchase orders format for display
        const convertedOrders: PurchaseOrder[] = approvedRequests.map((pr: PurchaseRequest) => ({
          id: parseInt(pr.id) || hashString(pr.id),
          po_number: pr.pr_number || pr.id,
          supplier_id: 0,
          supplier: {
            id: 0,
            name: pr.entity_name || pr.requested_by || 'N/A',
            address: '',
            province: '',
            contact_person: '',
            phone: '',
            email: '',
            bir_tin: '',
            is_active: true,
            created_at: pr.date_created,
            updated_at: pr.date_updated || pr.date_created
          },
          delivery_address: pr.office_section,
          notes: pr.remark || '',
          status: 'Approved' as const,
          total_amount: pr.total_amount,
          date_created: pr.date_created,
          date_updated: pr.date_updated || pr.date_created,
          items: pr.items.map((item, index) => ({
            id: index + 1,
            product_id: index + 1,
            product: {
              id: index + 1,
              name: item.item_description,
              unit: item.unit,
              unit_price: item.unit_cost,
              category: '',
              is_active: true,
              description: ''
            },
            quantity: item.quantity,
            unit_price: item.unit_cost,
            total_price: item.total_cost
          }))
        }));
        
        setOrders(convertedOrders);
        setPurchaseRequests(approvedRequests);
      } catch (error) {
        console.error('Error fetching data:', error);
        setOrders([]);
      }
    } catch (error) {
      console.error('Failed to fetch data:', error);
      setOrders([]);
    } finally {
      setLoading(false);
    }
  };

  const hashString = (str: string): number => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }
    return Math.abs(hash);
  };

  const handleViewOrder = (order: PurchaseOrder) => {
    setSelectedOrder(order);
    // Initialize inspection data with order items
    setInspectionData({
      inspection_date: new Date().toISOString().split('T')[0],
      inspected_by: user?.full_name || user?.username || '',
      items: order.items.map(item => ({
        item_description: item.product.name,
        quantity_received: item.quantity,
        quantity_ordered: item.quantity,
        condition: 'Good' as const,
        remarks: ''
      })),
      overall_remarks: '',
      status: 'Pending'
    });
    setShowModal(true);
  };

  const handleSubmitInspection = async () => {
    if (!selectedOrder) return;

    try {
      // Here you would typically submit the inspection report to the backend
      // For now, we'll just show a success message
      setToastMessage('Inspection and Acceptance Report submitted successfully');
      setToastType('success');
      setShowToast(true);
      setShowModal(false);
      
      // Refresh the list
      await fetchData();
    } catch (error: any) {
      console.error('Failed to submit inspection:', error);
      setToastMessage(error.response?.data?.message || 'Failed to submit inspection report');
      setToastType('error');
      setShowToast(true);
    }
  };

  const updateItemField = (index: number, field: string, value: any) => {
    const newItems = [...inspectionData.items];
    newItems[index] = { ...newItems[index], [field]: value };
    setInspectionData({ ...inspectionData, items: newItems });
  };

  const formatCurrency = (amount: number): string => {
    return new Intl.NumberFormat('en-PH', {
      style: 'currency',
      currency: 'PHP',
    }).format(amount);
  };

  const formatDate = (dateString: string): string => {
    return new Date(dateString).toLocaleDateString('en-PH', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  const getStatusBadge = (status: string) => {
    const statusConfig = {
      'Draft': { variant: 'secondary', text: 'Draft' },
      'Pending': { variant: 'warning', text: 'Pending' },
      'Approved': { variant: 'success', text: 'Approved' },
      'Completed': { variant: 'primary', text: 'Completed' },
      'Cancelled': { variant: 'danger', text: 'Cancelled' },
    };

    const config = statusConfig[status as keyof typeof statusConfig] || { 
      variant: 'secondary', 
      text: status 
    };

    return <Badge bg={config.variant}>{config.text}</Badge>;
  };

  const filteredOrders = orders.filter(order =>
    order.po_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
    order.supplier.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    order.status.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <Container className="py-4">
        <LoadingSpinner size="lg" text="Loading inspection data..." />
      </Container>
    );
  }

  return (
    <Container className="py-4">
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <div className="d-flex justify-content-between align-items-center">
            <div>
              <h2 className="mb-1">Inspection and Acceptance Report</h2>
              <p className="text-muted mb-0">
                Inspect and accept received items from purchase orders
              </p>
            </div>
          </div>
        </Col>
      </Row>

      {/* Search */}
      <Row className="mb-4">
        <Col md={6}>
          <InputGroup>
            <InputGroup.Text>
              <i className="bi bi-search"></i>
            </InputGroup.Text>
            <Form.Control
              type="text"
              placeholder="Search orders..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              aria-label="Search orders"
            />
          </InputGroup>
        </Col>
      </Row>

      {/* Orders Table */}
      <Card>
        <Card.Header>
          <h5 className="mb-0">Purchase Orders Ready for Inspection</h5>
        </Card.Header>
        <Card.Body className="p-0">
          {filteredOrders.length > 0 ? (
            <div className="table-responsive">
              <Table striped bordered className="mb-0">
                <thead>
                  <tr>
                    <th>PO/PR Number</th>
                    <th>Supplier/Entity</th>
                    <th>Date Created</th>
                    <th>Status</th>
                    <th>Total Amount</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredOrders.map((order) => (
                    <tr key={order.id}>
                      <td>
                        <strong>{order.po_number}</strong>
                      </td>
                      <td>{order.supplier.name}</td>
                      <td>{formatDate(order.date_created)}</td>
                      <td>{getStatusBadge(order.status)}</td>
                      <td>
                        <strong>{formatCurrency(order.total_amount)}</strong>
                      </td>
                      <td>
                        <Button
                          variant="primary"
                          size="sm"
                          onClick={() => handleViewOrder(order)}
                        >
                          <i className="bi bi-clipboard-check me-1"></i>
                          Inspect
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            </div>
          ) : (
            <div className="text-center py-5">
              <i className="bi bi-clipboard-check text-muted" style={{ fontSize: '3rem' }}></i>
              <p className="text-muted mt-3">
                {searchTerm ? 'No orders found matching your search' : 'No purchase orders ready for inspection'}
              </p>
            </div>
          )}
        </Card.Body>
      </Card>

      {/* Inspection Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="xl">
        <Modal.Header closeButton>
          <Modal.Title>Inspection and Acceptance Report</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedOrder && (
            <>
              {/* Order Information */}
              <Card className="mb-4">
                <Card.Header className="bg-primary text-white">
                  <h5 className="mb-0">Order Information</h5>
                </Card.Header>
                <Card.Body>
                  <Row>
                    <Col md={6}>
                      <p><strong>PO/PR Number:</strong> {selectedOrder.po_number}</p>
                      <p><strong>Supplier/Entity:</strong> {selectedOrder.supplier.name}</p>
                    </Col>
                    <Col md={6}>
                      <p><strong>Date Created:</strong> {formatDate(selectedOrder.date_created)}</p>
                      <p><strong>Total Amount:</strong> {formatCurrency(selectedOrder.total_amount)}</p>
                    </Col>
                  </Row>
                </Card.Body>
              </Card>

              {/* Inspection Details */}
              <Card className="mb-4">
                <Card.Header className="bg-primary text-white">
                  <h5 className="mb-0">Inspection Details</h5>
                </Card.Header>
                <Card.Body>
                  <Row className="g-3">
                    <Col md={6}>
                      <Form.Group>
                        <Form.Label>Inspection Date *</Form.Label>
                        <Form.Control
                          type="date"
                          value={inspectionData.inspection_date}
                          onChange={(e) => setInspectionData({ ...inspectionData, inspection_date: e.target.value })}
                        />
                      </Form.Group>
                    </Col>
                    <Col md={6}>
                      <Form.Group>
                        <Form.Label>Inspected By *</Form.Label>
                        <Form.Control
                          type="text"
                          value={inspectionData.inspected_by}
                          onChange={(e) => setInspectionData({ ...inspectionData, inspected_by: e.target.value })}
                          readOnly
                          className="bg-light"
                        />
                      </Form.Group>
                    </Col>
                  </Row>
                </Card.Body>
              </Card>

              {/* Items Inspection */}
              <Card className="mb-4">
                <Card.Header className="bg-primary text-white">
                  <h5 className="mb-0">Items Inspection</h5>
                </Card.Header>
                <Card.Body className="p-0">
                  <div className="table-responsive">
                    <Table striped bordered className="mb-0">
                      <thead className="bg-light">
                        <tr>
                          <th>Item Description</th>
                          <th>Quantity Ordered</th>
                          <th>Quantity Received</th>
                          <th>Condition</th>
                          <th>Remarks</th>
                        </tr>
                      </thead>
                      <tbody>
                        {inspectionData.items.map((item, index) => (
                          <tr key={index}>
                            <td>{item.item_description}</td>
                            <td>{item.quantity_ordered}</td>
                            <td>
                              <Form.Control
                                type="number"
                                min="0"
                                value={item.quantity_received}
                                onChange={(e) => updateItemField(index, 'quantity_received', Number(e.target.value))}
                              />
                            </td>
                            <td>
                              <Form.Select
                                value={item.condition}
                                onChange={(e) => updateItemField(index, 'condition', e.target.value)}
                              >
                                <option value="Good">Good</option>
                                <option value="Defective">Defective</option>
                                <option value="Damaged">Damaged</option>
                              </Form.Select>
                            </td>
                            <td>
                              <Form.Control
                                type="text"
                                value={item.remarks}
                                onChange={(e) => updateItemField(index, 'remarks', e.target.value)}
                                placeholder="Enter remarks..."
                              />
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </Table>
                  </div>
                </Card.Body>
              </Card>

              {/* Overall Remarks */}
              <Card>
                <Card.Header className="bg-primary text-white">
                  <h5 className="mb-0">Overall Remarks</h5>
                </Card.Header>
                <Card.Body>
                  <Form.Group>
                    <Form.Label>Remarks</Form.Label>
                    <Form.Control
                      as="textarea"
                      rows={4}
                      value={inspectionData.overall_remarks}
                      onChange={(e) => setInspectionData({ ...inspectionData, overall_remarks: e.target.value })}
                      placeholder="Enter overall inspection remarks..."
                    />
                  </Form.Group>
                  <Form.Group className="mt-3">
                    <Form.Label>Status *</Form.Label>
                    <Form.Select
                      value={inspectionData.status}
                      onChange={(e) => setInspectionData({ ...inspectionData, status: e.target.value as any })}
                    >
                      <option value="Pending">Pending</option>
                      <option value="Accepted">Accepted</option>
                      <option value="Partial">Partial</option>
                      <option value="Rejected">Rejected</option>
                    </Form.Select>
                  </Form.Group>
                </Card.Body>
              </Card>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Cancel
          </Button>
          <Button variant="primary" onClick={handleSubmitInspection}>
            <i className="bi bi-check-circle me-2"></i>
            Submit Inspection Report
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Toast Notification */}
      <Toast
        show={showToast}
        message={toastMessage}
        type={toastType}
        onClose={() => setShowToast(false)}
      />
    </Container>
  );
};

export default Inspection;
